        key = "rol", levels = "16-22",
        intro = {
            "Above the Undercity: the portal is in the open Ruins of Lordaeron, reached from Tirisfal south of Brill. Five players, levels 16-22.",
            "Spiders first in King's Alley, then skeletons and banshees, flesh golems on Lordamere Overlook and ghoul packs in close quarters: pull one pack at a time.",
            "Quests to take before going in (Horde): The Wrath of Rath'mael (Brill), A Frightened Request and The New Plague (the Sepulcher), Light's Justice (the Apothecarium). Inside: Abominable Creatures from Captain Truman at the entrance; Bloodied Insignia drops from the undead.",
        },
        stops = {
            { npc = 250483, kind = "boss", name = "Witherfang", title = "Plague spider", quests = { 95216 },
              approach = { "From the entrance go down the stairs to the east; skip the webbed gate by jumping through the window on its right.",
                  "Walks King's Alley (the east side) with her broodlings: kill them first, or pull her alone from range." },
              mechanics = { "Leech Poison on the tank: cleanse it. Stuns help.", "The New Plague: loot the toxic strain." } },
            { npc = 250660, kind = "boss", name = "The Baron", title = "Abomination", quests = { 95250 },
              approach = { "Go south along the east wall; where three ghostly citizens stand, turn west into the passage.",
                  "With the skeletal soldiers and banshees; clear them first (banshees silence).",
                  "After him: climb the broken pillar behind him and jump the low wall." },
              mechanics = { "Knockout: a big hit that also drops threat; keep the tank topped up and stun it when you can.",
                  "His head starts Unending Torment; Abominable Creatures wants it too." } },
            { npc = 256035, kind = "boss", name = "Viktor the Vile", title = "Wave event",
              approach = { "Light the fire in the chimney of the house to the southwest on Lordamere Overlook, by the graveyard.",
                  "Five waves of adds come first, then Viktor." },
              mechanics = { "Heavy melee and the same Leech Poison as Witherfang: let the tank take him first." } },
            { npc = 250631, kind = "boss", name = "The Abandoned", title = "Wave event",
              approach = { "Where Lordamere Overlook meets Market Street: the statue starts three waves, then him." },
              mechanics = { "Frost Nova, and hitting him in melee chills you; Drain Life on the tank." } },
            { npc = 256097, kind = "boss", name = "Bjork", title = "Undead brute",
              approach = { "After The Abandoned: through the narrow stairway, turn right and jump through the big window. He walks the north-west part." },
              mechanics = { "Only a short Anti-Magic Shield: wait it out with spells, keep hitting." } },
            { npc = 250657, kind = "boss", name = "Rath'mael", title = "Last boss", quests = { 92422 },
              approach = { "After Bjork go straight south to the fenced graveyard with the summoning circle." },
              mechanics = { "Flamestrike lands where the tank stood when he began it: everyone move out. Stuns stop it.",
                  "The Wrath of Rath'mael: kill him. Remember That I Love You (Alliance) starts from an item beside him." } },
        },
    },
    -- WoW Forever's own The Hall of Thanes (area 16919; its instance id isn't known: found by name, ns.NamedGuide). Facts from
    -- wowf.io and wowsrc.com, the words ours; ids from QuestieDB Forever (0.1.55).
    [16919] = {
        key = "hot", levels = "13-16", names = { "The Hall of Thanes", "Hall of Thanes" },
        intro = {
            "Under Ironforge: the way in is the left-hand path down from King Magni's throne room into Old Ironforge. Five players, levels 13-16.",
            "Ghosts fill the first hall, Dark Iron dwarves and their summoners hold the middle, stone golems guard the end. The way down runs over lava: a fall can't be climbed back, so stay on the path.",
            "Quests: Old Ironforge Incursion (Earthseer Farsen, Dun Morogh), The Restless Dead (Afadra Dunwall) and Important Heirlooms (Thom Filch) in Ironforge; An Ancient Grudge from the Ghostly Attendant inside, for both factions.",
            "Horde has to cross Ironforge to get in: the guards will likely kill you, so take your gear off before the gates (unworn gear loses no durability).",
        },
        stops = {
            { npc = 261306, kind = "boss", name = "Faldrim Anvilmar", title = "Restless thane", quests = { 96395, 96394 },
              approach = { "In Anvilmar's Rest, the big hall just past the entrance, among Enraged Apparitions and Tormented Souls: clear the room around him first.", "The Ghostly Attendant just outside the hall gives An Ancient Grudge." },
              mechanics = { "Mind Blast: interrupt it.", "Anvilmar's Curse slows the tank's attacks: remove it if you can." } },
            { npc = 261316, kind = "boss", name = "Magmatus", title = "Fire elemental",
              approach = { "East from Anvilmar's Rest, deep in the Dark Iron Ingress.", "A Dark Iron Summoner stands with him: kill the summoner first, or it keeps calling adds." },
              mechanics = { "Combust burns a player for 12 seconds and can't be interrupted: heal through it.", "Fire Nova around him: ranged players stay back." } },
            { npc = 261311, kind = "boss", name = "Plunder", title = "Golem",
              approach = { "West from Magmatus into the big square hall of the thanes' thrones; he walks his own hallway.", "Pull him into a cleared corner." },
              mechanics = { "Knock Away throws players back, into other packs if you're careless: fight with your backs to a wall." } },
            { npc = 261319, kind = "boss", name = "Durgen Dirgehammer", title = "Last boss", quests = { 96393 },
              approach = { "North from Plunder, past the corridor of dwarven banners, into the Reliquary of Kings.", "Clear the Dark Iron Looters along the sides first; on the way, pull the two stone golems back off the bridge." },
              mechanics = { "Kill the Lesser Stone Golems with him first.", "Rend on the tank, and an 8-second Fear that scatters the group into other packs: clear the room before the pull.", "Old Ironforge Incursion: loot his head." } },
        },
    },
    -- WoW Forever's own Excavation Site: Wetlands (area 16732; its instance id isn't known: found by name, ns.NamedGuide). Facts from
    -- wowf.io and wowsrc.com, the words ours; ids from QuestieDB Forever (0.1.55).
    [16732] = {
        key = "exca", levels = "28-31", names = { "Excavation Site: Wetlands", "Excavation Site", "Excavation Sites" },
        intro = {
            "In the Wetlands: the portal is on the hill south-east of Whelgar's Excavation Site (47.8, 56.3), the meeting stone at 53.4, 65.3. Five players, levels 28-31.",
            "Elite crocolisks first, then the raptors of Stalker's Thicket with Dragonmaw casters among them, and a stone golem at the end.",
            "Nobody has written up these bosses' abilities yet: watch what they do.",
            "Quests: Alliance from Menethil Harbor and the Wetlands (Highland Hides, Horrors in the Highland, Lost Relic Carry, Songblade Search, Lost in the Thicket Things); Horde: Changing Tastes, Open the Maw and Elder Knowledge.",
        },
        stops = {
            { npc = 260322, kind = "boss", name = "Saltspine", title = "Crocolisk",
              approach = { "The Lost Marsh, the first area past the portal." },
              mechanics = { "No write-up of its abilities yet: watch what it does." } },
            { npc = 260325, kind = "boss", name = "Shadetooth", title = "Raptor", quests = { 98815, 95697 },
              approach = { "Stalker's Thicket, among elite raptors (lurkers, hunters, a matriarch) and Dragonmaw Thaumaturgists: pull slowly." },
              mechanics = { "No write-up of its abilities yet: watch what it does.", "Highland Hides and Changing Tastes: he and the thicket raptors drop the hides and the meat." } },
            { npc = 260808, kind = "boss", name = "Highland Horror", title = "Bog beast", optional = true, quests = { 95646 },
              approach = { "May not always be here: it was added late, and has been seen outside the dungeon at Wetlands 49.0, 63.5." },
              mechanics = { "No write-up of its abilities yet: watch what it does.", "Horrors in the Highland: loot its rootcore." } },
            { npc = 260326, kind = "boss", name = "Relic Guardian", title = "Last boss", quests = { 95810, 95664 },
              approach = { "The Site of the Guardian at the end of the dig." },
              mechanics = { "No write-up of its abilities yet: watch what it does.", "It drops the Titan Relic: Lost Relic Carry (Alliance), Elder Knowledge (Horde)." } },
        },
    },
    -- WoW Forever's own City of Dalaran (area 16544; its instance id isn't known: found by name, ns.NamedGuide). Facts from
    -- wowf.io and wowsrc.com, the words ours; ids from QuestieDB Forever (0.1.55).
    [16544] = {
        key = "dal", levels = "30-33", names = { "City of Dalaran", "Dalaran" },
        intro = {
            "The mage city on Lordamere Lake, in Alterac Mountains. The way in is through the sewers, and one player in the group needs the Dalaran Sewer Key. Five players, levels 30-33.",
            "The key comes with Heart of Disruption from the Image of Archmage Modera, east of Silverpine Forest. Alliance first takes An Alarming Request from Emissary Jacques in Hillsbrad; Horde first does Magus Wordeen Voidglare's quests in Tarren Mill.",
            "Inside: the sewers and the Underbelly first, then the city streets, and the Violet Citadel last.",
        },
        stops = {
            { npc = 247126, kind = "boss", name = "Atrexis the Grave Knight", title = "Grave knight", quests = { 96986 },
              approach = { "On the Underbelly floor past the sewers, at the ritual circle in the middle, with Kirin Tor Necromancers." },
              mechanics = { "Skeletons keep rising: they're weak, kill them as they come.", "Disarms the tank for a few seconds." } },
            { npc = 247032, kind = "rare", name = "Lyn the Ignored", title = "Rare: summoned", optional = true,
              approach = { "Summoned with the Tome of Dalaran on the ritual circle in the small round room of the sewers.", "The tome: take the Black Tome from behind Arugal at the end of Shadowfang Keep and use it on the crystal at Ambermill in Silverpine Forest (63.4, 64.3)." },
              mechanics = { "No write-up of its abilities yet: watch what it does." } },
            { npc = 245999, kind = "boss", name = "Arcane Anomaly", title = "Arcane elemental",
              approach = { "In the streets: pulled out of its bubble on the Round Terrace." },
              mechanics = { "Focal Blast: a 3-second cast, then a 6-second beam straight ahead. Get out of its path when the cast starts.", "Arcane Bolt on the tank between beams." } },
            { npc = 246003, kind = "boss", name = "Fel Ancient", title = "Corrupted ancient",
              approach = { "Runeweaver Square in the middle of the city, with Suffused Treants around it." },
              mechanics = { "Fel Timbers run to one player and hit everyone within 5 yards of them: spread out.", "Poison fumes stay on the ground afterwards: move out of them." } },
            { npc = 246016, kind = "boss", name = "Arcanic Enigma", title = "Mana elemental", quests = { 92489 },
              approach = { "Power Overwhelming (Alliance) asks for it as the Mana Elemental." },
              mechanics = { "Manamorph turns a player into a critter for 8 seconds: dispel it, it's magic.", "A 10-second silence: healers keep their distance.", "Small Arcane Manalings: kill them with area damage." } },
            { npc = 246017, kind = "boss", name = "Unstable Sentinel", title = "Arcane construct", quests = { 96988 },
              approach = { "At the Magus Commerce Exchange. Angry Tomes come at you on the way: kill them before the pull." },
              mechanics = { "Malfunction: a 2-second cast, then it hits everyone within 25 yards every 2 seconds for 6 seconds. Ranged stay beyond 25 yards, melee step out during the cast.", "Source of Power (Horde): Cracked Sentry Cores." } },
            { npc = 246008, kind = "boss", name = "Mana Devourer", title = "Boss",
              approach = { "Near the gardens in the south of the city." },
              mechanics = { "No write-up of its abilities yet: watch what it does." } },
            { npc = 246020, kind = "boss", name = "Shade of the Archmage", title = "Last boss", quests = { 92458, 96984 },
              approach = { "At the top of the Violet Citadel in the north-west: the NPC in front of the Citadel teleports you up to the Purple Parlor." },
              mechanics = { "Bounding Mana flies to a player and back: anyone in its path takes damage and is silenced for 6 seconds. Don't stand between them.", "Out of mana, he polymorphs the whole group for 8 seconds, then channels Evocation for 6: burn him then.", "Anyone leaving the room resets him to full health.", "Heart of Disruption: loot the Arcane Mote." } },
        },
    },
}
ns.DungeonGuides = GUIDES
